-- query_capiro_data / describe_capiro_data: state the answer rules for grants and
-- contract notices on meri_public.federal_grants and meri_public.sam_opportunities
-- (20281102140000 and 20281102170000, immutable once applied).
--
-- Neo's funding search handoff (2 November 2026): a grant is open only when posted
-- with a close date not passed or unset, forecasted grants are reported separately,
-- a null close date is an unknown deadline (read response_date_desc), award ceiling
-- and estimated funding are not money awarded, a current notice is active with a
-- response deadline not passed or unset, notice_type decides whether offers are
-- taken, solicitation_number is not a unique notice id, and award winners are a
-- different dataset. 20281102140000 published "open" as posted or forecasted (the
-- ingestion's priority predicate, funding-catalog.reconcile.ts), which let an answer
-- call a forecast open. This migration replaces both view comments and nine column
-- comments. Comments only: no view definition, grant, policy, role or row changes.
SET ROLE capiro_public_projection_owner;

COMMENT ON VIEW meri_public.federal_grants IS '{"description":"Federal grant opportunities from Grants.gov as synchronized by Capiro, one row per opportunity: posted, forecasted, closed and archived. Accepting applications (open) means status = ''posted'' AND (close_date IS NULL OR close_date >= CURRENT_DATE). Forecasted grants (status = ''forecasted'') are announced but not yet accepting applications: report them separately and call them forecasted, never open. A null close_date is an unknown or unspecified deadline: read response_date_desc before calling an opportunity continuously open.","grain":"One row per (grants_gov_id), the Grants.gov opportunity id.","primaryKey":["grants_gov_id"],"relationships":[],"limitations":["Published metadata does not establish active grants, populated rows, ingestion completeness or source freshness.","Only the opportunities Capiro synchronized; a missing opportunity is absence within this ingestion, not on Grants.gov.","status can lag the source between synchronizations; always combine it with close_date as described for open.","award_ceiling is the most one award can receive, award_floor the least, estimated_funding the total program funding and expected_awards the announced number of awards, all as announced; never sum them, none of them is money already awarded, and many rows leave them null.","category, funding_instrument, eligibility and eligibility_text come from detail enrichment and are null on most archived rows.","This relation holds the synopsis only; requirements stated in the full announcement and its attached documents are not here, so a requirement missing from these columns is not proof it is absent.","Who received awards is the separate federal_assistance_awards relation (its funding_opportunity_number or assistance_listing_number); never infer recipients or awarded amounts from this relation."],"freshnessField":"synced_at"}';
COMMENT ON COLUMN meri_public.federal_grants.status IS '{"description":"Grants.gov lifecycle status: posted (accepting applications while close_date is null or not yet passed), forecasted (announced, not yet accepting applications; report separately), closed or archived. Open is status = ''posted'' AND (close_date IS NULL OR close_date >= CURRENT_DATE).","enum":["posted","forecasted","closed","archived"]}';
COMMENT ON COLUMN meri_public.federal_grants.close_date IS '{"description":"Application close date, or for a forecast the estimated close date. Null means the deadline is unknown or unspecified, not that the opportunity closed and not proof that it is continuous: read response_date_desc and say what it states."}';
COMMENT ON COLUMN meri_public.federal_grants.response_date_desc IS '{"description":"Publisher text explaining the close date, e.g. continuous, rolling, TBD or an explicit Eastern Time cutoff; read it whenever close_date is null or a deadline is quoted. Null when not stated."}';
COMMENT ON COLUMN meri_public.federal_grants.award_ceiling IS '{"description":"Announced maximum one award can receive, in US dollars; not money awarded. Null when not stated.","unit":"USD"}';
COMMENT ON COLUMN meri_public.federal_grants.estimated_funding IS '{"description":"Announced estimated total program funding in US dollars across all awards; not an award amount and not money awarded. Null when not stated.","unit":"USD"}';
COMMENT ON COLUMN meri_public.federal_grants.opportunity_number IS '{"description":"Funding opportunity number as published by the agency; not unique across revisions of a program. federal_assistance_awards.funding_opportunity_number holds the same number when the award source published it."}';

COMMENT ON VIEW meri_public.sam_opportunities IS '{"description":"SAM.gov contract opportunity notices as synchronized by Capiro, one row per notice: solicitations, presolicitations, sources sought, special and award notices. A current notice is active AND (response_deadline IS NULL OR response_deadline >= now()). For opportunities accepting bids or offers also filter notice_type: Solicitation and Combined Synopsis/Solicitation take offers; Presolicitation and Sources Sought gather interest before a solicitation; Award Notice and Justification and Approval (J&A) report a decision and are never open; Special Notice is informational.","grain":"One row per (notice_id), the SAM.gov notice id.","primaryKey":["notice_id"],"relationships":[],"limitations":["Published metadata does not establish active grants, populated rows, ingestion completeness or source freshness.","Only the notices Capiro synchronized; a missing notice is absence within this ingestion, not on SAM.gov.","active is the provider''s flag at synchronization and can be true after the response window has closed; also test response_deadline.","notice_type is the current type after amendments and is truncated to 32 characters. Award Notice rows announce awards, not open competitions.","base_type and archive_date are null on every notice the current writer loads; a value appears only on notices from an earlier writer, so never filter or count by them.","pop_state is null when the notice did not state a two-letter place-of-performance state.","solicitation_number is not a unique notice identifier: every notice of one procurement shares it. Count and cite notices by notice_id; group by solicitation_number only to count procurements.","This relation holds the notice text only; requirements in attached solicitation documents are not here, so a requirement missing from these columns is not proof it is absent.","Who won a contract is the separate federal_awards relation and no published key links a notice to its award; never name a winner from this relation."],"freshnessField":"last_synced_at"}';
COMMENT ON COLUMN meri_public.sam_opportunities.notice_type IS '{"description":"Current SAM.gov notice type, truncated to 32 characters; values seen include Combined Synopsis/Solicitation, Solicitation, Award Notice, Sources Sought, Special Notice, Presolicitation (also spelled Pre solicitation) and Justification and Approval (J&A). Solicitation and Combined Synopsis/Solicitation take offers; Presolicitation and Sources Sought gather interest; Award Notice and J&A are never open. Filter with ILIKE to catch both spellings.","nullable":false}';
COMMENT ON COLUMN meri_public.sam_opportunities.solicitation_number IS '{"description":"Solicitation number as published; not a unique notice identifier: every notice of one procurement (presolicitation, solicitation, amendments, award) shares it."}';
COMMENT ON COLUMN meri_public.sam_opportunities.response_deadline IS '{"description":"Response or offer due date and time (UTC); null when the notice states none, common for sources sought and award notices. A current notice has a null or not yet passed response_deadline."}';

RESET ROLE;
